#include "milp/FeasibilityPump.hpp"
#include <cassert>
using namespace sovereign;
int main(){Model m;m.sense=Sense::Minimize;m.variables.push_back({0,0,"x",VariableType::Integer,0,INF,true});m.variables.push_back({1,1,"b",VariableType::Binary,0,1,true});m.variables.push_back({2,2,"c",VariableType::Continuous,0,INF,true});m.objective[0]=-3;m.objective[1]=-2;Constraint c;c.name="cap";c.coefficients[0]=2;c.coefficients[1]=2;c.coefficients[2]=1;c.relation=Relation::LessEqual;c.rhs=3;m.constraints.push_back(c);auto r=FeasibilityPump{1e-7,30}.solve(m);assert(r.status==FpStatus::Feasible);assert(r.verified);assert(r.projections>0);assert(std::abs(r.solution[0]-std::round(r.solution[0]))<1e-7);assert(r.solution[1]==0||r.solution[1]==1);assert(r.solution[2]!=std::round(r.solution[2])||r.solution[2]>=0);assert(m.variables[0].type==VariableType::Integer);
 Model impossible;impossible.variables.push_back({0,0,"x",VariableType::Integer,0,INF,true});Constraint e;e.coefficients[0]=2;e.relation=Relation::Equal;e.rhs=1;impossible.constraints.push_back(e);auto no=FeasibilityPump{1e-7,8}.solve(impossible);assert(no.status==FpStatus::NoFeasibleSolution);assert(!no.verified);return 0;}
